static class Pipeline {
    public static long authorize(long amount, long available, long daily_used, long daily_limit, bool blocked) {
        if (blocked) {
            return (-1);
        }
        if ((amount <= 0)) {
            return (-2);
        }
        if ((daily_used < 0)) {
            return (-3);
        }
        long remaining = (daily_limit - daily_used);
        if ((remaining < amount)) {
            return (-4);
        }
        if ((available < amount)) {
            return (-5);
        }
        long reserved = (available - amount);
        if ((reserved < 100)) {
            return 1;
        }
        return 0;
    }

    public static long capture(long authorized, long requested, long captured, bool expired) {
        if (expired) {
            return (-1);
        }
        if ((requested <= 0)) {
            return (-2);
        }
        long remaining = (authorized - captured);
        if ((remaining <= 0)) {
            return (-3);
        }
        if ((requested > remaining)) {
            return (-4);
        }
        long total = (captured + requested);
        if ((total == authorized)) {
            return 2;
        }
        if ((total < authorized)) {
            return 1;
        }
        return (-5);
    }

    public static long refund(long captured, long refunded, long requested, bool disputed) {
        if (disputed) {
            return (-1);
        }
        if ((refunded < 0)) {
            return (-2);
        }
        if ((requested <= 0)) {
            return (-3);
        }
        long available = (captured - refunded);
        if ((requested > available)) {
            return (-4);
        }
        long total = (refunded + requested);
        if ((total == captured)) {
            return 2;
        }
        return 1;
    }

    public static long allocate_refund(long[] lines, long refund_total) {
        if ((refund_total <= 0)) {
            return 0;
        }
        long remaining = refund_total;
        long allocated = 0;
        for (long i = 0; i < lines.Length; i++) {
            long value = lines[(int)(i)];
            if ((value <= 0)) {
                continue;
            }
            long share = System.Math.Min(value, remaining);
            allocated += share;
            remaining -= share;
            if ((remaining == 0)) {
                break;
            }
        }
        if ((remaining > 0)) {
            return (-remaining);
        }
        return allocated;
    }

    public static long settlement_net(long[] captures, long[] refunds, long fee_bps) {
        if (((fee_bps < 0) || (fee_bps > 10000))) {
            return (-1);
        }
        long gross = 0;
        for (long i = 0; i < captures.Length; i++) {
            if ((captures[(int)(i)] < 0)) {
                return (-2);
            }
            gross += captures[(int)(i)];
        }
        long returned = 0;
        for (long i = 0; i < refunds.Length; i++) {
            if ((refunds[(int)(i)] < 0)) {
                return (-3);
            }
            returned += refunds[(int)(i)];
        }
        if ((returned > gross)) {
            return (-4);
        }
        long net = (gross - returned);
        long fee = ((net * fee_bps) / 10000);
        return (net - fee);
    }

    public static long tax_inclusive(long gross, long rate, bool exempt) {
        if ((gross < 0)) {
            return (-1);
        }
        if (exempt) {
            return 0;
        }
        if ((rate < 0)) {
            return (-2);
        }
        long denominator = (10000 + rate);
        long numerator = (gross * rate);
        long rounding = (denominator / 2);
        long tax = ((numerator + rounding) / denominator);
        if ((tax > gross)) {
            return (-3);
        }
        return tax;
    }

    public static long exchange(long amount, long numerator, long denominator, long minimum) {
        if ((amount < 0)) {
            return (-1);
        }
        if ((numerator <= 0)) {
            return (-2);
        }
        if ((denominator <= 0)) {
            return (-3);
        }
        long scaled = (amount * numerator);
        long converted = ((scaled + (denominator / 2)) / denominator);
        if ((converted < minimum)) {
            return 0;
        }
        if ((converted > 1000000000)) {
            return (-4);
        }
        return converted;
    }

    public static long dispute_reserve(long[] amounts, long[] ages, long max_age) {
        if ((amounts.Length != ages.Length)) {
            return (-1);
        }
        long total = 0;
        for (long i = 0; i < amounts.Length; i++) {
            if ((ages[(int)(i)] < 0)) {
                return (-2);
            }
            if ((ages[(int)(i)] > max_age)) {
                continue;
            }
            if ((amounts[(int)(i)] <= 0)) {
                continue;
            }
            total += amounts[(int)(i)];
        }
        if ((total == 0)) {
            return 0;
        }
        return (total + (total / 10));
    }

    public static long retry_delay(long attempt, long initial, long cap, long jitter) {
        if (((attempt < 0) || (initial <= 0))) {
            return (-1);
        }
        long delay = initial;
        long count = 0;
        while ((count < attempt)) {
            if ((delay >= (cap / 2))) {
                delay = cap;
                break;
            }
            delay *= 2;
            count += 1;
        }
        long bounded = System.Math.Min(delay, cap);
        if ((jitter < 0)) {
            jitter = 0;
        }
        return System.Math.Min((bounded + jitter), cap);
    }

    public static long retryable(long status, long attempt, long maximum, bool idempotent) {
        if ((!idempotent)) {
            return 0;
        }
        if ((attempt >= maximum)) {
            return 0;
        }
        if ((status == 429)) {
            return 1;
        }
        if ((status == 408)) {
            return 1;
        }
        if ((status >= 500)) {
            if ((status < 600)) {
                return 1;
            }
        }
        if ((status == 0)) {
            return 1;
        }
        return 0;
    }

    public static long reserve_stock(long on_hand, long reserved, long requested, bool backorder) {
        if ((requested <= 0)) {
            return (-1);
        }
        if ((reserved < 0)) {
            return (-2);
        }
        long available = (on_hand - reserved);
        if ((requested > available)) {
            if (backorder) {
                return 2;
            }
            return (-3);
        }
        long after = (available - requested);
        if ((after == 0)) {
            return 1;
        }
        return 0;
    }

    public static long reorder_point(long[] demand, long lead_days, long safety) {
        if ((demand.Length == 0)) {
            return safety;
        }
        if ((lead_days <= 0)) {
            return (-1);
        }
        long total = 0;
        long peak = 0;
        for (long i = 0; i < demand.Length; i++) {
            if ((demand[(int)(i)] < 0)) {
                return (-2);
            }
            total += demand[(int)(i)];
            peak = System.Math.Max(peak, demand[(int)(i)]);
        }
        long average = (((total + demand.Length) - 1) / demand.Length);
        long seasonal = System.Math.Max(average, (peak / 2));
        return ((seasonal * lead_days) + safety);
    }

    public static long pick_batch(long[] stock, long needed, long max_locations) {
        long remaining = needed;
        long visited = 0;
        for (long i = 0; i < stock.Length; i++) {
            if ((remaining <= 0)) {
                break;
            }
            if ((visited >= max_locations)) {
                return (-remaining);
            }
            if ((stock[(int)(i)] <= 0)) {
                continue;
            }
            long picked = System.Math.Min(stock[(int)(i)], remaining);
            remaining -= picked;
            visited += 1;
        }
        if ((remaining > 0)) {
            return (-remaining);
        }
        return visited;
    }

    public static long reconcile_stock(long[] expected, long[] counted, long tolerance) {
        if ((expected.Length != counted.Length)) {
            return (-1);
        }
        long discrepancy = 0;
        long critical = 0;
        for (long i = 0; i < expected.Length; i++) {
            long delta = System.Math.Abs((counted[(int)(i)] - expected[(int)(i)]));
            if ((delta == 0)) {
                continue;
            }
            discrepancy += delta;
            if ((delta > tolerance)) {
                critical += 1;
            }
        }
        if ((critical > 0)) {
            return (-critical);
        }
        return discrepancy;
    }

    public static long transfer_stock(long source, long target, long requested, long capacity) {
        if ((requested <= 0)) {
            return (-1);
        }
        if ((source < requested)) {
            return (-2);
        }
        if ((target < 0)) {
            return (-3);
        }
        long space = (capacity - target);
        if ((space <= 0)) {
            return (-4);
        }
        long moved = System.Math.Min(requested, space);
        if ((moved < requested)) {
            return (-5);
        }
        return (target + moved);
    }

    public static long expiry_loss(long[] quantities, long[] expiry_days, long today) {
        if ((quantities.Length != expiry_days.Length)) {
            return (-1);
        }
        long expired = 0;
        for (long i = 0; i < quantities.Length; i++) {
            if ((quantities[(int)(i)] < 0)) {
                return (-2);
            }
            if ((expiry_days[(int)(i)] > today)) {
                continue;
            }
            expired += quantities[(int)(i)];
        }
        if ((expired == 0)) {
            return 0;
        }
        return expired;
    }

    public static long bundle_capacity(long[] stock, long[] per_bundle) {
        if ((stock.Length != per_bundle.Length)) {
            return (-1);
        }
        if ((stock.Length == 0)) {
            return 0;
        }
        long bundles = 1000000;
        for (long i = 0; i < stock.Length; i++) {
            if ((per_bundle[(int)(i)] <= 0)) {
                return (-2);
            }
            long possible = (stock[(int)(i)] / per_bundle[(int)(i)]);
            bundles = System.Math.Min(bundles, possible);
        }
        if ((bundles < 0)) {
            return 0;
        }
        return bundles;
    }

    public static long shipping_cost(long weight, long distance, bool fragile, bool express) {
        if (((weight <= 0) || (distance < 0))) {
            return (-1);
        }
        long shipping_base = 350;
        if ((weight > 5000)) {
            shipping_base += ((((weight - 5000) + 999) / 1000) * 80);
        }
        if ((distance > 100)) {
            shipping_base += ((distance - 100) * 2);
        }
        if (fragile) {
            shipping_base += 200;
        }
        if (express) {
            shipping_base = ((shipping_base * 3) / 2);
        }
        return shipping_base;
    }

    public static long order_total(long[] prices, long[] quantities, long discount) {
        if ((prices.Length != quantities.Length)) {
            return (-1);
        }
        if (((discount < 0) || (discount > 10000))) {
            return (-2);
        }
        long subtotal = 0;
        for (long i = 0; i < prices.Length; i++) {
            if ((prices[(int)(i)] < 0)) {
                return (-3);
            }
            if ((quantities[(int)(i)] <= 0)) {
                return (-4);
            }
            subtotal += (prices[(int)(i)] * quantities[(int)(i)]);
        }
        long reduction = ((subtotal * discount) / 10000);
        return (subtotal - reduction);
    }

    public static long cancellation_fee(long paid, bool dispatched, long hours, long fee_bps) {
        if ((paid < 0)) {
            return (-1);
        }
        if (dispatched) {
            return paid;
        }
        if ((hours < 0)) {
            return (-2);
        }
        if ((hours <= 1)) {
            return 0;
        }
        long fee = ((paid * fee_bps) / 10000);
        if ((fee < 100)) {
            fee = System.Math.Min(paid, 100);
        }
        return System.Math.Min(fee, paid);
    }

    public static long fulfillment_state(long ordered, long packed, long shipped, long returned) {
        if ((ordered <= 0)) {
            return (-1);
        }
        if ((returned > shipped)) {
            return (-2);
        }
        if (((shipped > packed) || (packed > ordered))) {
            return (-3);
        }
        if ((returned == ordered)) {
            return 5;
        }
        if ((shipped == ordered)) {
            return 4;
        }
        if ((shipped > 0)) {
            return 3;
        }
        if ((packed > 0)) {
            return 2;
        }
        return 1;
    }

    public static long split_payment(long balance, long gift, long total, long minimum_charge) {
        if ((total <= 0)) {
            return (-1);
        }
        long covered = System.Math.Min(gift, total);
        long remaining = (total - covered);
        if ((remaining == 0)) {
            return 0;
        }
        if ((remaining < minimum_charge)) {
            remaining = minimum_charge;
        }
        if ((remaining > balance)) {
            return (-2);
        }
        return remaining;
    }

    public static long authenticate(long now, long expires, long issued, bool revoked) {
        if (revoked) {
            return (-1);
        }
        if ((issued > (now + 30))) {
            return (-2);
        }
        if ((expires <= issued)) {
            return (-3);
        }
        if ((now >= expires)) {
            return (-4);
        }
        long age = (now - issued);
        if ((age < 0)) {
            return 1;
        }
        if ((age > 86400)) {
            return 2;
        }
        return 0;
    }

    public static long login_lockout(long[] failures, long now, long window, long maximum) {
        long recent = 0;
        long earliest = now;
        for (long i = 0; i < failures.Length; i++) {
            if ((failures[(int)(i)] > now)) {
                continue;
            }
            long age = (now - failures[(int)(i)]);
            if ((age < window)) {
                recent += 1;
                earliest = System.Math.Min(earliest, failures[(int)(i)]);
            }
        }
        if ((recent >= maximum)) {
            return System.Math.Max(1, ((earliest + window) - now));
        }
        return 0;
    }

    public static long permission(long role, bool owner, bool suspended, bool write) {
        if (suspended) {
            return 0;
        }
        if ((role == 3)) {
            return 1;
        }
        if (write) {
            if ((role < 2)) {
                return 0;
            }
            if ((!owner)) {
                return 0;
            }
        }
        if ((role == 0)) {
            return 0;
        }
        return 1;
    }

    public static long session_refresh(long now, long last_seen, long issued, long idle, long lifetime) {
        if ((last_seen < issued)) {
            return (-1);
        }
        if ((now < last_seen)) {
            return (-2);
        }
        long idle_age = (now - last_seen);
        if ((idle_age >= idle)) {
            return (-3);
        }
        long total_age = (now - issued);
        if ((total_age >= lifetime)) {
            return (-4);
        }
        long remaining = System.Math.Min((idle - idle_age), (lifetime - total_age));
        return System.Math.Max(0, remaining);
    }

    public static long quota_remaining(long limit, long consumed, long pending, bool trusted) {
        if ((limit < 0)) {
            return (-1);
        }
        if (((consumed < 0) || (pending < 0))) {
            return (-2);
        }
        long effective = limit;
        if (trusted) {
            effective += (limit / 10);
        }
        long remaining = ((effective - consumed) - pending);
        if ((remaining <= 0)) {
            return 0;
        }
        return remaining;
    }

    public static long cache_lifetime(long now, long created, long accessed, long ttl, long idle) {
        if (((created > now) || (accessed > now))) {
            return (-1);
        }
        long absolute = (created + ttl);
        long sliding = (accessed + idle);
        long deadline = System.Math.Min(absolute, sliding);
        if ((deadline <= now)) {
            return 0;
        }
        long remaining = (deadline - now);
        if ((remaining > ttl)) {
            return ttl;
        }
        return remaining;
    }

    public static long eviction_candidate(long[] hits, long[] ages, long[] pinned) {
        if (((hits.Length != ages.Length) || (ages.Length != pinned.Length))) {
            return (-1);
        }
        long candidate = (-1);
        long worst = (-1);
        for (long i = 0; i < hits.Length; i++) {
            if ((pinned[(int)(i)] != 0)) {
                continue;
            }
            long score = ((ages[(int)(i)] * 1000) / (hits[(int)(i)] + 1));
            if ((score > worst)) {
                candidate = i;
                worst = score;
            }
        }
        return candidate;
    }

    public static long cache_admission(long size, long capacity, long used, long hit_rate) {
        if ((size <= 0)) {
            return (-1);
        }
        if ((size > (capacity / 4))) {
            return 0;
        }
        long available = (capacity - used);
        if ((size <= available)) {
            return 1;
        }
        if ((hit_rate < 20)) {
            return 0;
        }
        long required = (size - available);
        if ((required > (capacity / 10))) {
            return 0;
        }
        return 2;
    }

    public static long lease_job(long now, long lease_until, long attempts, long max_attempts, bool cancelled) {
        if (cancelled) {
            return (-1);
        }
        if ((attempts >= max_attempts)) {
            return (-2);
        }
        if ((lease_until > now)) {
