        }
        return (now + duration);
    }

    public static long schedule_priority(long created, long now, long priority, long failures) {
        if ((created > now)) {
            return (-1);
        }
        long age = (now - created);
        long aging = (age / 60);
        long score = ((priority * 100) + aging);
        if ((failures > 0)) {
            long penalty = System.Math.Min((failures * 20), 200);
            score -= penalty;
        }
        if ((score < 0)) {
            return 0;
        }
        return System.Math.Min(score, 10000);
    }

    public static long batch_checkpoint(long[] offsets, long committed, long max_gap) {
        long next_offset = committed;
        for (long i = 0; i < offsets.Length; i++) {
            long value = offsets[(int)(i)];
            if ((value <= next_offset)) {
                continue;
            }
            if (((value - next_offset) > max_gap)) {
                break;
            }
            if ((value != (next_offset + 1))) {
                return next_offset;
            }
            next_offset = value;
        }
        if ((next_offset < committed)) {
            return (-1);
        }
        return next_offset;
    }

