        if (((hour < 0) || (hour > 23))) {
            return (-1);
        }
        if (urgent) {
            return 1;
        }
        if ((start == end)) {
            return 1;
        }
        if ((start < end)) {
            if (((hour >= start) && (hour < end))) {
                return 1;
            }
            return 0;
        }
        if (((hour >= start) || (hour < end))) {
            return 1;
        }
        return 0;
    }

    public static long digest_count(long[] events, long since, long until, long limit) {
        if ((until < since)) {
            return (-1);
        }
        long count = 0;
        for (long i = 0; i < events.Length; i++) {
            if ((events[(int)(i)] < since)) {
                continue;
            }
            if ((events[(int)(i)] >= until)) {
                continue;
            }
            count += 1;
            if ((count >= limit)) {
                break;
            }
        }
        if ((count == 0)) {
            return 0;
        }
        return count;
    }

    public static long deduplicate(long[] ids, long incoming, long high_water) {
        if ((incoming < 0)) {
            return (-1);
        }
        if ((incoming <= high_water)) {
            for (long i = 0; i < ids.Length; i++) {
                if ((ids[(int)(i)] == incoming)) {
                    return 0;
                }
            }
        }
        if ((incoming > (high_water + 1000))) {
            return (-2);
        }
        if ((incoming == high_water)) {
            return 0;
        }
        return 1;
    }

    public static long event_partition(long key, long partitions, long old_partitions, bool migrating) {
        if ((partitions <= 0)) {
            return (-1);
        }
        long positive = System.Math.Abs(key);
        long current = (positive % partitions);
        if ((!migrating)) {
            return current;
        }
        if ((old_partitions <= 0)) {
            return (-2);
        }
        long previous = (positive % old_partitions);
        if ((previous == current)) {
            return current;
        }
        return (partitions + previous);
    }

    public static long watermark(long[] timestamps, long now, long lateness) {
        long candidate = (now - lateness);
        for (long i = 0; i < timestamps.Length; i++) {
            if ((timestamps[(int)(i)] < 0)) {
                return (-1);
            }
            if ((timestamps[(int)(i)] > now)) {
                continue;
            }
            long event_bound = (timestamps[(int)(i)] - lateness);
            if ((event_bound < candidate)) {
                candidate = event_bound;
            }
        }
        if ((candidate < 0)) {
            return 0;
        }
        return candidate;
    }

    public static long rate_window(long[] samples, long now, long width, long limit) {
        if (((width <= 0) || (limit <= 0))) {
            return (-1);
        }
        long accepted = 0;
        for (long i = 0; i < samples.Length; i++) {
            if ((samples[(int)(i)] > now)) {
                continue;
            }
            if ((samples[(int)(i)] > (now - width))) {
                accepted += 1;
            }
        }
        if ((accepted >= limit)) {
            return 0;
        }
        long remaining = (limit - accepted);
        return remaining;
    }

    public static long health_score(long[] latencies, long errors, long requests) {
        if ((requests <= 0)) {
            return 100;
        }
        if ((errors > requests)) {
            return (-1);
        }
        long slow = 0;
        for (long i = 0; i < latencies.Length; i++) {
            if ((latencies[(int)(i)] > 500)) {
                slow += 1;
            }
        }
        long availability = (((requests - errors) * 100) / requests);
        long penalty = System.Math.Min((slow * 2), 30);
        long score = (availability - penalty);
        return System.Math.Max(0, score);
    }

    public static long retention_cutoff(long now, long days, bool legal_hold, long archive_days) {
        if (legal_hold) {
            return (-1);
        }
        if ((days <= 0)) {
            return (-2);
        }
        long effective = System.Math.Max(days, archive_days);
        long seconds = (effective * 86400);
        if ((seconds > now)) {
            return 0;
        }
        long cutoff = (now - seconds);
        if ((cutoff < 0)) {
            return 0;
        }
        return cutoff;
    }
}

