}

func allocate_refund(lines []int64, refund_total int64) int64 {
    if (refund_total <= 0) {
        return 0
    }
    var remaining int64 = refund_total
    var allocated int64 = 0
    for i := int64(0); i < int64(len(lines)); i++ {
        var value int64 = lines[i]
        if (value <= 0) {
            continue
        }
        var share int64 = min64(value, remaining)
        allocated += share
        remaining -= share
        if (remaining == 0) {
            break
        }
    }
    if (remaining > 0) {
        return (-remaining)
    }
    return allocated
}

func settlement_net(captures []int64, refunds []int64, fee_bps int64) int64 {
    if ((fee_bps < 0) || (fee_bps > 10000)) {
        return (-1)
    }
    var gross int64 = 0
    for i := int64(0); i < int64(len(captures)); i++ {
        if (captures[i] < 0) {
            return (-2)
        }
        gross += captures[i]
    }
    var returned int64 = 0
    for i := int64(0); i < int64(len(refunds)); i++ {
        if (refunds[i] < 0) {
            return (-3)
        }
        returned += refunds[i]
    }
    if (returned > gross) {
        return (-4)
    }
    var net int64 = (gross - returned)
    var fee int64 = ((net * fee_bps) / 10000)
    return (net - fee)
}

func tax_inclusive(gross int64, rate int64, exempt bool) int64 {
    if (gross < 0) {
        return (-1)
    }
    if exempt {
        return 0
    }
    if (rate < 0) {
        return (-2)
    }
    var denominator int64 = (10000 + rate)
    var numerator int64 = (gross * rate)
    var rounding int64 = (denominator / 2)
    var tax int64 = ((numerator + rounding) / denominator)
    if (tax > gross) {
        return (-3)
    }
    return tax
}

func exchange(amount int64, numerator int64, denominator int64, minimum int64) int64 {
    if (amount < 0) {
        return (-1)
    }
    if (numerator <= 0) {
        return (-2)
    }
    if (denominator <= 0) {
        return (-3)
    }
    var scaled int64 = (amount * numerator)
    var converted int64 = ((scaled + (denominator / 2)) / denominator)
    if (converted < minimum) {
        return 0
    }
    if (converted > 1000000000) {
        return (-4)
    }
    return converted
}

func dispute_reserve(amounts []int64, ages []int64, max_age int64) int64 {
    if (int64(len(amounts)) != int64(len(ages))) {
