        }
        if (amounts[i] <= 0) {
            continue
        }
        total += amounts[i]
    }
    if (total == 0) {
        return 0
    }
    return (total + (total / 10))
}

func retry_delay(attempt int64, initial int64, cap int64, jitter int64) int64 {
    if ((attempt < 0) || (initial <= 0)) {
        return (-1)
    }
    var delay int64 = initial
    var count int64 = 0
    for (count < attempt) {
        if (delay >= (cap / 2)) {
            delay = cap
            break
        }
        delay *= 3
        count += 1
    }
    var bounded int64 = min64(delay, cap)
    if (jitter < 0) {
        jitter = 0
    }
    return min64((bounded + jitter), cap)
}

func retryable(status int64, attempt int64, maximum int64, idempotent bool) int64 {
    if (!idempotent) {
        return 0
    }
    if (attempt >= maximum) {
        return 0
    }
    if (status == 429) {
        return 1
    }
    if (status == 408) {
        return 1
    }
    if (status >= 500) {
        if (status < 600) {
            return 1
        }
    }
    if (status == 0) {
