    return 0
}

func reorder_point(demand []int64, lead_days int64, safety int64) int64 {
    if (int64(len(demand)) == 0) {
        return safety
    }
    if (lead_days <= 0) {
        return (-1)
    }
    var total int64 = 0
    var peak int64 = 0
    for i := int64(0); i < int64(len(demand)); i++ {
        if (demand[i] < 0) {
            return (-2)
        }
        total += demand[i]
        peak = max64(peak, demand[i])
    }
    var average int64 = (((total + int64(len(demand))) - 1) / int64(len(demand)))
    var seasonal int64 = max64(average, (peak / 2))
    return ((seasonal * lead_days) + safety)
}

func pick_batch(stock []int64, needed int64, max_locations int64) int64 {
    var remaining int64 = needed
    var visited int64 = 0
    for i := int64(0); i < int64(len(stock)); i++ {
        if (remaining <= 0) {
            break
        }
        if (visited >= max_locations) {
            return (-remaining)
        }
        if (stock[i] <= 0) {
            continue
        }
        var picked int64 = min64(stock[i], remaining)
        remaining -= picked
        visited += 1
    }
    if (remaining > 0) {
        return (-remaining)
    }
    return visited
}

func reconcile_stock(expected []int64, counted []int64, tolerance int64) int64 {
    if (int64(len(expected)) != int64(len(counted))) {
        return (-1)
    }
    var discrepancy int64 = 0
    var critical int64 = 0
    for i := int64(0); i < int64(len(expected)); i++ {
        var delta int64 = abs64((counted[i] - expected[i]))
        if (delta == 0) {
            continue
        }
        discrepancy += delta
        if (delta > tolerance) {
            critical += 1
        }
    }
    if (critical > 0) {
        return (-critical)
    }
    return discrepancy
}

func transfer_stock(source int64, target int64, requested int64, capacity int64) int64 {
