    }
    if (shipped == ordered) {
        return 4
    }
    if (shipped > 0) {
        return 3
    }
    if (packed > 0) {
        return 2
    }
    return 1
}

func split_payment(balance int64, gift int64, total int64, minimum_charge int64) int64 {
