        }
    }
    if (role == 0) {
        return 0
    }
    return 1
}

func session_refresh(now int64, last_seen int64, issued int64, idle int64, lifetime int64) int64 {
    if (last_seen < issued) {
        return (-1)
    }
    if (now < last_seen) {
        return (-2)
    }
    var idle_age int64 = (now - last_seen)
    if (idle_age >= idle) {
        return (-3)
    }
    var total_age int64 = (now - issued)
    if (total_age >= lifetime) {
        return (-4)
    }
    var remaining int64 = min64((idle - idle_age), (lifetime - total_age))
    return max64(0, remaining)
}

func quota_remaining(limit int64, consumed int64, pending int64, trusted bool) int64 {
    if (limit < 0) {
        return (-1)
    }
    if ((consumed < 0) || (pending < 0)) {
        return (-2)
    }
    var effective int64 = limit
    if trusted {
        effective += (limit / 10)
    }
    var remaining int64 = ((effective - consumed) - pending)
    if (remaining <= 0) {
        return 0
    }
    return remaining
}

func cache_lifetime(now int64, created int64, accessed int64, ttl int64, idle int64) int64 {
    if ((created > now) || (accessed > now)) {
        return (-1)
    }
    var absolute int64 = (created + ttl)
    var sliding int64 = (accessed + idle)
    var deadline int64 = min64(absolute, sliding)
    if (deadline <= now) {
        return 0
    }
    var remaining int64 = (deadline - now)
    if (remaining > ttl) {
        return ttl
    }
    return remaining
}

func eviction_candidate(hits []int64, ages []int64, pinned []int64) int64 {
    if ((int64(len(hits)) != int64(len(ages))) || (int64(len(ages)) != int64(len(pinned)))) {
        return (-1)
    }
    var candidate int64 = (-1)
    var worst int64 = (-1)
    for i := int64(0); i < int64(len(hits)); i++ {
        if (pinned[i] != 0) {
            continue
        }
        var score int64 = ((ages[i] * 1000) / (hits[i] + 1))
        if (score > worst) {
            candidate = i
            worst = score
        }
    }
    return candidate
}

func cache_admission(size int64, capacity int64, used int64, hit_rate int64) int64 {
    if (size <= 0) {
        return (-1)
    }
    if (size > (capacity / 4)) {
        return 0
    }
    var available int64 = (capacity - used)
    if (size <= available) {
        return 1
    }
    if (hit_rate < 20) {
        return 0
    }
    var required int64 = (size - available)
    if (required > (capacity / 10)) {
        return 0
    }
    return 2
}

func lease_job(now int64, lease_until int64, attempts int64, max_attempts int64, cancelled bool) int64 {
