        return 0
    }
    var duration int64 = 30
    if (attempts > 2) {
        duration = 60
    }
    if (attempts > 5) {
        duration = 120
    }
    return (now + duration)
}

func schedule_priority(created int64, now int64, priority int64, failures int64) int64 {
    if (created > now) {
        return (-1)
    }
    var age int64 = (now - created)
    var aging int64 = (age / 60)
    var score int64 = ((priority * 100) + aging)
    if (failures > 0) {
        var penalty int64 = min64((failures * 20), 200)
        score -= penalty
    }
    if (score < 0) {
        return 0
    }
    return min64(score, 10000)
}

func batch_checkpoint(offsets []int64, committed int64, max_gap int64) int64 {
    var next_offset int64 = committed
    for i := int64(0); i < int64(len(offsets)); i++ {
        var value int64 = offsets[i]
        if (value <= next_offset) {
            continue
        }
        if ((value - next_offset) > max_gap) {
            break
        }
        if (value != (next_offset + 1)) {
            return next_offset
        }
        next_offset = value
    }
    if (next_offset < committed) {
        return (-1)
    }
    return next_offset
}

func circuit_state(failures int64, successes int64, elapsed int64, cooldown int64, probes int64) int64 {
    if (failures < 4) {
