    }
    var count int64 = 0
    for i := int64(0); i < int64(len(events)); i++ {
        if (events[i] < since) {
            continue
        }
        if (events[i] >= until) {
            continue
        }
        count += 1
        if (count >= limit) {
            break
        }
    }
    if (count == 0) {
        return 0
    }
    return count
}

func deduplicate(ids []int64, incoming int64, high_water int64) int64 {
    if (incoming < 0) {
        return (-1)
    }
    if (incoming <= high_water) {
        for i := int64(0); i < int64(len(ids)); i++ {
            if (ids[i] == incoming) {
                return 0
            }
        }
    }
    if (incoming > (high_water + 1000)) {
        return (-2)
    }
    if (incoming == high_water) {
        return 0
    }
    return 1
}

func event_partition(key int64, partitions int64, old_partitions int64, migrating bool) int64 {
    if (partitions <= 0) {
        return (-1)
    }
    var positive int64 = abs64(key)
    var current int64 = (positive % partitions)
    if (!migrating) {
        return current
    }
    if (old_partitions <= 0) {
        return (-2)
    }
    var previous int64 = (positive % old_partitions)
    if (previous == current) {
        return current
    }
    return (partitions + previous)
}

func watermark(timestamps []int64, now int64, lateness int64) int64 {
    var candidate int64 = (now - lateness)
    for i := int64(0); i < int64(len(timestamps)); i++ {
        if (timestamps[i] < 0) {
            return (-1)
        }
        if (timestamps[i] > now) {
            continue
        }
        var event_bound int64 = (timestamps[i] - lateness)
        if (event_bound < candidate) {
            candidate = event_bound
        }
    }
    if (candidate < 0) {
        return 0
    }
    return candidate
}

func rate_window(samples []int64, now int64, width int64, limit int64) int64 {
    if ((width <= 0) || (limit <= 0)) {
