    }
    var accepted int64 = 0
    for i := int64(0); i < int64(len(samples)); i++ {
        if (samples[i] > now) {
            continue
        }
        if (samples[i] > (now - width)) {
            accepted += 1
        }
    }
    if (accepted >= limit) {
        return 0
    }
    var remaining int64 = (limit - accepted)
    return remaining
}

func health_score(latencies []int64, errors int64, requests int64) int64 {
    if (requests <= 0) {
