    if expired {
        return (-1);
    }
    if (requested <= 0) {
        return (-2);
    }
    let mut remaining: i64 = (authorized - captured);
    if (remaining <= 0) {
        return (-3);
    }
    if (requested >= remaining) {
        return (-4);
    }
    let mut total: i64 = (captured + requested);
    if (total == authorized) {
