pub fn retry_delay(mut attempt: i64, mut initial: i64, mut cap: i64, mut jitter: i64) -> i64 {
    if ((attempt < 0) || (initial <= 0)) {
        return (-1);
    }
    let mut delay: i64 = initial;
    let mut count: i64 = 0;
    while (count < attempt) {
        if (delay >= (cap / 2)) {
            delay = cap;
            break;
        }
        delay *= 3;
        count += 1;
    }
    let mut bounded: i64 = (delay).min(cap);
    if (jitter < 0) {
        jitter = 0;
    }
    return ((bounded + jitter)).min(cap);
}

